// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof zgbmv, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 14', function test( t ) {
	t.strictEqual( zgbmv.length, 14, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided an invalid first argument', function test( t ) {
	var values;
	var alpha;
	var data;
	var beta;
	var i;
	var a;
	var x;
	var y;

	data = rnt;

	a = new Complex128Array( data.A );
	x = new Complex128Array( data.x );
	y = new Complex128Array( data.y );

	alpha = new Complex128( data.alpha[0], data.alpha[1] );
	beta = new Complex128( data.beta[0], data.beta[1] );

	values = [
		'foo',
		'bar',
		'beep',
		'boop'
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			zgbmv( value, data.trans, data.M, data.N, data.KL, data.KU, alpha, a, data.lda, x, data.strideX, beta, y, data.strideY );
		};
	}
});

